namespace Joey.LookAndFeel;

/// <summary>Confirmed part of 00457500/00457520. The native constructor
/// stores count and result bits; these are not generated by the visual.
/// Particle/reflection passes remain separate until their ABI is resolved.</summary>
public sealed class NativeCoinTimeline
{
    public const int StartCounter = -128, UpdateIncrement = 8, Layer = 0x110;
    public const uint LaunchSound = 0x1000001d;
    public int Count { get; }
    public uint ResultBits { get; }
    public CardPoint Origin { get; }
    public int Counter { get; private set; } = StartCounter;
    public int EndCounter => (Count+4)*128;
    public int Updates => (EndCounter-StartCounter)/UpdateIncrement;
    public bool Active => Counter < EndCounter;

    // Observed handlers E0 and E1 (compressed indices 8E/8F) supply one or three coins.
    public NativeCoinTimeline(int count, uint resultBits, CardPoint origin)
    {
        if (count is not (1 or 3)) throw new ArgumentOutOfRangeException(nameof(count));
        Count = count;
        ResultBits = resultBits;
        Origin = origin;
    }

    public void AdvanceNativeUpdate()
    {
        if (Active) Counter += UpdateIncrement;
    }

    public NativeCoinSample Sample(int index, ReadOnlySpan<int> cosine)
    {
        if (!Active) throw new InvalidOperationException("Coin object is inactive.");
        if (index < 0 || index >= Count) throw new ArgumentOutOfRangeException(nameof(index));
        NativeFusionMath.Validate(cosine);
        int t = Counter-index*128;
        int bounce = t is >= 0 and < 256 ?
            NativeFusionMath.C(cosine,(t & 255)-128)>>7 : 0;
        int x = 525+(100-Count*100)/2+100*index;
        var target = new CardPoint(x,300);
        var center = t < 0 ? Origin : t > 256 ? target :
            new((Origin.X*(256-t)+x*t)/256,(Origin.Y*(256-t)+300*t)/256);
        return new(t,center,bounce,bounce/2+256,(ResultBits & (1u<<index)) != 0,
            t == 0 ? LaunchSound : null);
    }
}

public readonly record struct NativeCoinSample(int LocalCounter, CardPoint Center,
    int Bounce, int ScaleFixed8, bool ResultBit, uint? SoundRequest);

public readonly record struct NativeBreakParticle(CardBounds Bounds, int Intensity)
{
    // 0045105E..00451071 changes DL only; preserve the high bits of
    // the angle. Intensity is the low byte, not a proven blend factor.
    public int RawCompositorArgument { get; init; }
}

/// <summary>00450FB0/00450FD0. Five original resource-0 particles precede
/// a separate card distortion pass (00558FB0). No generic Destroy mapping.</summary>
public sealed class NativeBreakTimeline
{
    public const int EndCounter=256, UpdateIncrement=16, Updates=16;
    public const int ReleaseCounter=64;
    public const uint SoundRequest=0x10000008;
    public const int ParticleKey=0, ParticleCount=5;
    public int Counter { get; private set; }
    public bool Active => Counter < EndCounter;

    // Vtable 005DB314 +4 = 00450E50 (CMP counter,40h / SETL).
    // The object can still be drawn after this query stops blocking.
    public bool BlocksRelease => Counter < ReleaseCounter;

    public void AdvanceNativeUpdate()
    {
        if (Active) Counter += UpdateIncrement;
    }

    public NativeBreakParticle[] Particles(CardPoint center,int width,int height,ReadOnlySpan<int> cosine)
    {
        NativeFusionMath.Validate(cosine);
        if (width <= 0 || height <= 0) throw new ArgumentOutOfRangeException(nameof(width));
        if (!Active) return [];
        int radius=Counter/8;
        var result=new NativeBreakParticle[ParticleCount];
        for (int i=0;i<ParticleCount;i++)
        {
            int angle=i*512/5;
            int dx=unchecked(NativeFusionMath.C(cosine,angle)*radius)>>16;
            int dy=unchecked(NativeFusionMath.C(cosine,angle-128)*radius)>>16;
            result[i]=new(new(center.X+dx-width/2,center.Y+dy-height/2,width,height),255-Counter)
            { RawCompositorArgument=(angle & ~255) | (255-Counter) };
        }
        return result;
    }

    public int DistortionIntensity(ReadOnlySpan<int> cosine)
    {
        NativeFusionMath.Validate(cosine);
        return 256-(NativeFusionMath.C(cosine,Counter/2-128)>>8);
    }

    public static int CardRotationDegrees(ushort descriptor,int perspectiveBit)
    {
        if (perspectiveBit is not (0 or 1)) throw new ArgumentOutOfRangeException(nameof(perspectiveBit));
        return (((descriptor>>14)&1)+((descriptor&1)^perspectiveBit)*2)*90;
    }

    public static bool UsesHandCardBank(ushort descriptor) => (descriptor&0x3e)==0x16;
}
